import { useState, useEffect, useRef } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { motion, AnimatePresence} from "framer-motion";
import president from "../assets/comitee members/president.jpeg";
import sec from "../assets/comitee members/secratary.jpeg";
import lib from "../assets/comitee members/laibriy.jpeg";
import tre from "../assets/comitee members/treasurer.jpeg";
import muizz from "../assets/comitee members/muizz.jpeg";
import Arulselvi from "../assets/comitee members/Arulselvi.jpeg";
import ilayaraja from "../assets/comitee members/eliyarja.jpeg";
import kavi from "../assets/comitee members/Kavitha.jpeg";
import vasanth from "../assets/comitee members/vasanth.jpeg";
import partha from "../assets/comitee members/paratha.png";

// import SectionTitle from "./SectionTitle";
// import ConstitutionOfIndia from "./Constitution of India";
import "../Styles/Hero.css"; // Importing your plain CSS stylesheet

function Hero() {
  const slidesData = [
    {
      image: "https://plus.unsplash.com/premium_photo-1698084059560-9a53de7b816b?q=80&w=1111&auto=format&fit=crop",
      bearer: {
        role: "V.R.Kamalanathan",
        name: "President",
        term: "2026 - 2028",
        profileImage: president,
      },
    },
    {
      image: "https://lens.usercontent.google.com/banana?agsi=CmdnbG9iYWw6OjAwMDA1NWNmZWM3MDAyNmQ6MDAwMDAwZWI6MTo0M2MzOWRkMTBlZmY3MDRhOjAwMDA1NWNmZWM3MDAyNmQ6MDAwMDAyZGY5OTUwMzM2ODowMDA2NTdkNjA0NWJhMTJmEAIYASIJaW1hZ2UvcG5n",
      bearer: {
        role: "J.PothiRaj",
        name: "Secretary",
        term: "2026 - 2028",
        profileImage: sec,
      },
    },
    {
      image: "https://media.istockphoto.com/id/1218704953/photo/high-court-of-chennai-tamil-nadu-india-chennai-high-court.jpg?s=1024x1024&w=is&k=20&c=xcO6baJnfL8gGr7lIiQTgUduuj0UbyJVN4eYWoF7tSE=",
      bearer: {
        role: "V.T.Balaji",
        name: "Treasurer",
        term: "2026 - 2028",
        profileImage:tre ,
      },
    },
    {
      image: "https://media.istockphoto.com/id/1008159054/photo/law-and-justice.jpg?s=1024x1024&w=is&k=20&c=k0cy1BECrPWy2EhnImUJM_biv7BjWjL6GX3H_yJAN0U=",
      bearer: {
        role: "D.Raja",
        name: "Librarian",
        term: "2026 - 2028",
        profileImage: lib,
      },
    },
    {
      image: "https://cdnbbsr.s3waas.gov.in/s3ec0490f1f4972d133619a60c30f3559e/uploads/2023/10/SCI-banner.jpg",
      bearer: {
        role: "Muizz Ali",
        name: "Commttiee Member",
        term: "2026 - 2028",
        profileImage: muizz,
      },
    },
    {
      image: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS16Djq5vvvVluOpix_M_q4UxYnqlW7Mp3bVZixsc_1vQ&s=10",
      bearer: {
        role: "Kavitha Y",
        name: "Commttiee Member",
        term: "2026 - 2028",
        profileImage:kavi,
      },
    },
    {
      image: "https://static.toiimg.com/thumb/msid-124744496,width-1280,height-720,imgsize-2136835,resizemode-72,overlay-toi_sw,pt-32,y_pad-40/photo.jpg",
      bearer: {
        role: "Arul Selvi G",
        name: "Commttiee Member",
        term: "2026 - 2028",
        profileImage: Arulselvi,
      },
    },
    {
      image: "https://live.staticflickr.com/2776/4562214243_c867f73532_b.jpg",
      bearer: {
        role: "Elliyarajkumar",
        name: "Commttiee Member",
        term: "2026 - 2028",
        profileImage: ilayaraja,
      },
    },
    {
      image: "data:image/jpeg;base64,",
      bearer: {
        role: "Vasantha Kumar",
        name: "Commttiee Member",
        term: "2026 - 2028",
        profileImage: vasanth,
      },
    },
    {
      image: "https://media.istockphoto.com/id/1008159054/photo/law-and-justice.jpg?s=1024x1024&w=is&k=20&c=k0cy1BECrPWy2EhnImUJM_biv7BjWjL6GX3H_yJAN0U=",
      bearer: {
        role: "Arvind Srevatsa B",
        name: "Co-op Member",
        term: "2026 - 2028",
        profileImage: partha,
      },
    },
     
  ];

  const [currentSlide, setCurrentSlide] = useState(0);
  const [direction, setDirection] = useState(1);
  const timerRef = useRef(null);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const resetAutoPlay = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      handleNext();
    }, 4000);
  };

  const handleNext = () => {
    setDirection(1);
    setCurrentSlide((prev) => (prev + 1) % slidesData.length);
  };

  const handlePrev = () => {
    setDirection(-1);
    setCurrentSlide((prev) => (prev - 1 + slidesData.length) % slidesData.length);
  };

  useEffect(() => {
    resetAutoPlay();
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [currentSlide, resetAutoPlay]);

  const cardVariants = {
    enter: (dir) => ({ opacity: 0, x: dir > 0 ? 50 : -50 }),
    center: { opacity: 1, x: 0 },
    exit: (dir) => ({ opacity: 0, x: dir > 0 ? -50 : 50 }),
  };

  return (
    <section id="home" className="hero-section">
      {/* Background Slideshow Layer */}
      <div className="slideshow-container">
        {slidesData.map((slide, index) => (
          <div
            key={index}
            className={`slide-bg ${currentSlide === index ? "slide-active" : ""}`}
            style={{ backgroundImage: `url(${slide.image})` }}
          />
        ))}
        <div className="slideshow-overlay" />
      </div>

      {/* Decorative Blur Ambient Circles */}
      <div className="ambient-container">
        <div className="ambient-circle left-circle" />
        <div className="ambient-circle right-circle" />
      </div>
      <div className="blueprint-grid" />

      {/* Main Structural Content Grid */}
      <div className="hero-grid-wrapper">
        
        {/* Left Hand: Static Text Segment */}
        <motion.div
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }} /* Fixed text visibility setting */
          transition={{ duration: 0.9 }}
          className="left-branding-pane"
        >
        
          
           
        </motion.div>

        {/* Right Hand: Interactive Slate Panels */}
        <div className="right-slideshow-pane">

          <div className="cards-slider-viewport">
            <AnimatePresence initial={false} custom={direction} mode="wait">
              {slidesData.map((slide, index) => {
                if (index !== currentSlide) return null;
                const member = slide.bearer;

                return (
                  <motion.div
                    key={member.role}
                    custom={direction}
                    variants={cardVariants}
                    initial="enter"
                    animate="center"
                    exit="exit"
                    transition={{ duration: 0.4, ease: "easeInOut" }}
                    className="bearer-info-card"
                  >
                    {/* Top profile details header structure */}
                    <div className="card-header-block">
                      <div className="profile-image-mask">
                        <img
                          src={member.profileImage}
                          alt={member.name}
                          className="profile-img-element"
                        />
                      </div>
                      <div className="meta-text-block">
                        <p className="role-eyebrow-text">{member.role}</p>
                        <h3 className="member-display-name">{member.name}</h3>
                        <p className="member-tenure-text">Term {member.term}</p>
                      </div>
                    </div>

                    {/* Bottom Utility Controls Row */}
                    <div className="card-controls-row">
                      <div className="carousel-dot-indicator">
                        {slidesData.map((_, dotIdx) => (
                          <span
                            key={dotIdx}
                            className={`carousel-dot ${currentSlide === dotIdx ? "dot-active" : ""}`}
                            onClick={() => {
                              setDirection(dotIdx > currentSlide ? 1 : -1);
                              setCurrentSlide(dotIdx);
                            }}
                          />
                        ))}
                      </div>
                      
                      <div className="carousel-navigation-arrows">
                        <button className="nav-arrow-btn" onClick={handlePrev} aria-label="Previous">
                          <ChevronLeft size={20} />
                        </button>
                        <button className="nav-arrow-btn" onClick={handleNext} aria-label="Next">
                          <ChevronRight size={20} />
                        </button>
                      </div>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>
          </div>
        </div>

      </div>
    </section>
  );
}

export default Hero;
